  const response = await tenantStub(namespace, claims.teamId).fetch("https://do/actor-token/consume", {
    method: "POST",
    headers: { "content-type": "application/json" },
    body: JSON.stringify({
      jti: claims.jti,
      teamId: claims.teamId,
      actorId: claims.actor.id,
      rev: claims.rev,
      expiresAt: claims.exp * 1000,
