>): CandidateRerankFn | undefined {
  const mode = parseKnowledgeRerankMode(env.KNOWLEDGE_RERANK_MODE);
  if (mode === "off") return undefined;
  const apiKey = env.TYPESAFE_API_KEY?.trim();
