  env: Env,
  teamId: string,
  channelId: string,
  actorId: string,
): Promise<boolean> {
  let lease: SlackAclLease | undefined;
  try {
    lease = await acquireSlackAclLease(env, teamId, channelId, actorId);
    if (!lease) return false;
